import re
import subprocess
from pathlib import Path

MANIFEST_DIR = Path("/var/logistics/manifests")


def purge_stale_manifest_and_rerun_routing(depot_code: str, manifest_date: str):
    if not re.fullmatch(r"[A-Z]{3}\d{2}", depot_code or ""):
        return {"ok": False, "error": "invalid depot_code"}
    if not re.fullmatch(r"\d{4}-\d{2}-\d{2}", manifest_date or ""):
        return {"ok": False, "error": "manifest_date must be YYYY-MM-DD"}
    path = MANIFEST_DIR / depot_code / f"{manifest_date}.json"
    if not path.is_file():
        return {"ok": False, "error": "manifest not found"}
    path.unlink()
    proc = subprocess.run(
        ["/opt/logistics/bin/build_routes", "--depot", depot_code, "--date", manifest_date],
        capture_output=True,
        text=True,
    )
    if proc.returncode != 0:
        return {"ok": False, "error": proc.stderr.strip()}
    return proc.stdout.strip()
